    "questionAr": "موصل نحاسي طوله $L = 110\\text{ m}$ ومساحة مقطعه $A = 2 \\times 10^{-6}\\text{ m}^2$. إذا كانت المقاومة النوعية للنحاس $\\rho_e = 1.7 \\times 10^{-8}\\,\\Omega\\cdot\\text{m}$، فما مقاومة الموصل $R$؟",
