    "questionAr": "عمود كهربي قوته الدافعة $V_B = 36\\text{ V}$ ومقاومته الداخلية $r = 6\\,\\Omega$ يغذي دائرة خارجية فيمر تيار شدته $I = 3.6\\text{ A}$. ما فرق الجهد $V$ بين قطبي العمود؟",
