    "questionAr": "مصدر كهربي مستمر قوته الدافعة $V_B = 12\\text{ V}$ ومقاومته الداخلية $r = 2\\,\\Omega$ متصل بمقاومة حمل خارجية متغيرة $R_L$. ما أقصى قدرة كهربية $P_{\\max}$ يمكن نقلها إلى مقاومة الحمل؟",
